namespace sv_efea39558cda461aba55c8fc48ccc7c5.Services;

public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "warehouse-a";
    public string SelectedWarehouseName => Warehouses[SelectedWarehouseId];

    public static readonly Dictionary<string, string> Warehouses = new()
    {
        ["warehouse-a"] = "Warehouse A",
        ["warehouse-b"] = "Warehouse B",
        ["warehouse-c"] = "Warehouse C"
    };

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (SelectedWarehouseId == warehouseId) return;
        SelectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_efea39558cda461aba55c8fc48ccc7c5.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling and notifies all
/// subscribed components when new data arrives. Scoped lifetime ensures
/// each user circuit has independent state.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired whenever polling detects new data. All subscribed components
    /// receive this notification regardless of which triggered the poll.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Called by components to start polling. Polling begins on the first
    /// subscriber and stops when the last subscriber leaves.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            StartPolling();
        }
    }

    public void Unsubscribe()
    {
        _subscriberCount--;
        if (_subscriberCount <= 0)
        {
            _subscriberCount = 0;
            StopPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
        _cts?.Dispose();
        _cts = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire immediately on first subscribe
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task RefreshAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private void OnWarehouseChanged()
    {
        // When warehouse changes, refresh immediately if polling is active
        if (_subscriberCount > 0)
        {
            _ = RefreshAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        StopPolling();
    }
}

