@page "/dashboard"
@attribute [StreamRendering]
@rendermode InteractiveServer
@inject sv_efea39558cda461aba55c8fc48ccc7c5.Services.WarehouseState WarehouseState
@inject sv_efea39558cda461aba55c8fc48ccc7c5.Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-4">
    <div class="card-body">
        <h5 class="card-title">
            <span class="bi bi-exclamation-triangle-fill" aria-hidden="true"></span>
            Low Stock Alerts — @WarehouseState.SelectedWarehouseName
        </h5>
        <p class="card-text display-4">
            @AlertService.LowStockCount
            <small class="fs-6 text-muted">items below minimum level</small>
        </p>
        <p class="text-muted"><em>Refreshes automatically every 10 seconds</em></p>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        // Subscribe to polling — starts the timer if this is the first subscriber
        AlertService.Subscribe();

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
        // Unsubscribe — stops the timer if this was the last subscriber
        AlertService.Unsubscribe();
    }
}

